   395		if err != nil {
   396			status.State = "unsafe"
   397			status.Detail = err.Error()
   398			return status
   399		}
   400		if !local {
   401			status.State = "unknown"
   402			status.Detail = "local_path_hint unavailable"
   403			return status
   404		}
   405		dirs, err := resolvePluginDirs(opts.Env)
   406		if err != nil {
   407			status.State = "unsafe"
   408			status.Detail = err.Error()
   409			return status
